import test from "node:test";
import assert from "node:assert/strict";
import {assessVehicleSpecialRouting,VEHICLE_BODY_TYPES,assessSpecialVehicleEquipment,getVehicleBodyType,isSupportedVehicleBodyType} from "../../lib/vehicle-capabilities.mjs";
test("catalogue includes heavy vehicles and crane variants",()=>{for(const id of ["articulated_crane","telescopic_crane","loader_crane","heavy_lift_crane","mobile_crane","aerial_platform","recovery_crane","concrete_pump","rigid_truck","tractor_unit","semi_trailer","low_loader","tanker"])assert.equal(isSupportedVehicleBodyType(id),true,id);assert.equal(new Set(VEHICLE_BODY_TYPES.map(x=>x.id)).size,VEHICLE_BODY_TYPES.length);});
test("unknown body type fails closed",()=>assert.equal(assessSpecialVehicleEquipment({bodyType:"unknown"}).readyForRouting,false));
test("crane requires lifting chart and separate travel/work evidence",()=>{const r=assessSpecialVehicleEquipment({bodyType:"telescopic_crane",registrationVerified:true,equipmentDimensionsVerified:true,axleConfigurationVerified:true});assert.deepEqual(r.missing,["manufacturer_lifting_chart","travel_vs_working_configuration"]);});
test("fully evidenced crane passes evidence gate only",()=>{const r=assessSpecialVehicleEquipment({bodyType:"articulated_crane",registrationVerified:true,equipmentDimensionsVerified:true,axleConfigurationVerified:true,liftingChartVerified:true,operatingEnvelopeVerified:true});assert.equal(r.readyForRouting,true);});
test("ordinary rigid truck does not require crane chart",()=>{const r=assessSpecialVehicleEquipment({bodyType:"rigid_truck",registrationVerified:true,equipmentDimensionsVerified:true,axleConfigurationVerified:true});assert.equal(r.readyForRouting,true);assert.equal(getVehicleBodyType("rigid_truck").crane,false);});
const vehicle={id:"v-1",fleet_id:"f-1",body_type:"telescopic_crane"};
const equipment={vehicle_id:"v-1",fleet_id:"f-1",equipment_kind:"crane",evidence_status:"verified",evidence_verified_at:"2026-01-01",evidence_verified_by:"u-1",lifting_chart_document_path:"f-1/v-1/chart.pdf",travel_height_cm:390,travel_width_cm:250,travel_length_cm:1200,working_height_cm:3200,max_outreach_cm:1800,max_lifting_capacity_kg:5000,axle_configuration:"4 axles"};
test("verified crane profile passes with travel and work data",()=>assert.equal(assessVehicleSpecialRouting({vehicle,equipment}).ready,true));
test("crane fails closed without a profile or approval",()=>{assert.equal(assessVehicleSpecialRouting({vehicle,equipment:null}).reason,"special_equipment_profile_missing");assert.equal(assessVehicleSpecialRouting({vehicle,equipment:{...equipment,evidence_status:"pending"}}).reason,"special_equipment_evidence_not_verified");});
test("crane rejects evidence from another fleet",()=>assert.equal(assessVehicleSpecialRouting({vehicle,equipment:{...equipment,fleet_id:"other"}}).reason,"special_equipment_profile_missing"));
test("crane rejects chart path outside vehicle folder",()=>assert.equal(assessVehicleSpecialRouting({vehicle,equipment:{...equipment,lifting_chart_document_path:"other/chart.pdf"}}).reason,"lifting_chart_document_missing_or_misbound"));
test("crane rejects incomplete dimensions",()=>assert.equal(assessVehicleSpecialRouting({vehicle,equipment:{...equipment,travel_height_cm:null}}).reason,"special_equipment_configuration_incomplete"));
test("ordinary body type does not need equipment row",()=>assert.equal(assessVehicleSpecialRouting({vehicle:{...vehicle,body_type:"rigid_truck"},equipment:null}).ready,true));

test("special equipment kind must match classified body type",()=>assert.equal(assessVehicleSpecialRouting({vehicle,equipment:{...equipment,equipment_kind:"aerial_platform"}}).reason,"special_equipment_kind_mismatch"));
test("other special body requires a verified profile but no crane chart",()=>{const v={...vehicle,body_type:"other_special"};const e={...equipment,equipment_kind:"other_special",lifting_chart_document_path:null,working_height_cm:null,max_outreach_cm:null,max_lifting_capacity_kg:null};assert.equal(assessVehicleSpecialRouting({vehicle:v,equipment:e}).ready,true);});
